function B(s,a,n,o,f){const e=s[a]-n,h=s[a+1]-o,l=s[a+2]-f;return Math.sqrt(e*e+h*h+l*l)}function T(s,a){const{width:n,height:o,data:f}=s,e=new Uint8Array(n*o);let h=0,l=0,g=0,r=0;const c=(t,i)=>{const d=(i*n+t)*4;h+=f[d],l+=f[d+1],g+=f[d+2],r++};for(let t=0;t<n;t+=2)c(t,0),c(t,o-1);for(let t=0;t<o;t+=2)c(0,t),c(n-1,t);const x=[h/r,l/r,g/r],v=Math.max(1,a.tolerance),w=new Uint8Array(n*o),M=[],u=t=>{if(t<0||t>=n*o||w[t])return;const i=t*4;f[i+3]<10||B(f,i,x[0],x[1],x[2])<=v?(w[t]=1,e[t]=0,M.push(t)):(w[t]=2,e[t]=255)};for(let t=0;t<n;t++)u(t),u((o-1)*n+t);for(let t=0;t<o;t++)u(t*n),u(t*n+n-1);for(;M.length>0;){const t=M.pop(),i=t%n,d=(t-i)/n;i>0&&u(t-1),i<n-1&&u(t+1),d>0&&u(t-n),d<o-1&&u(t+n)}const p=Math.max(0,Math.round(a.feather));if(p>0){let t=e;for(let i=0;i<p;i++){const d=new Uint8Array(t.length);for(let y=0;y<o;y++)for(let m=0;m<n;m++){let E=0,I=0;for(let b=-1;b<=1;b++){const k=y+b;if(!(k<0||k>=o))for(let A=-1;A<=1;A++){const U=m+A;U<0||U>=n||(E+=t[k*n+U],I++)}}d[y*n+m]=Math.round(E/I)}t=d}e.set(t)}return{mask:e,backgroundEstimated:x}}function q(s,a,n){const{width:o,height:f,data:e}=s,h=new ImageData(o,f),l=h.data;for(let g=0;g<o*f;g++){const r=g*4,c=a[g]/255;l[r]=Math.round(e[r]*c+n[0]*(1-c)),l[r+1]=Math.round(e[r+1]*c+n[1]*(1-c)),l[r+2]=Math.round(e[r+2]*c+n[2]*(1-c)),l[r+3]=255}return h}function C(s,a){const n=new ImageData(new Uint8ClampedArray(s.data),s.width,s.height);for(let o=0;o<a.length;o++)n.data[o*4+3]=a[o];return n}export{q as c,T as m,C as r};
